def verifyInputs(self):
        """
        Used in propagate() to verify that the network input
        activations have been set.
        """
        if self.inputs is None:
            raise Exception("Inputs have not been set.")
        elif len(self.inputs) != self.input_size:
            raise Exception(f"Input size {len(self.inputs)} does not match network input size {self.input_size}.")

